let groupBy='continent',sortBy='change',trendView='heatmap',heatMeasure='level';
const historyLookup=new Map(DATA.countries.map(c=>[c.code,new Map(c.history)]));
function annualChange(c,year){const h=historyLookup.get(c.code),now=h.get(year),prior=h.get(year-1);return now===undefined||prior===undefined?undefined:Number((now-prior).toFixed(6));}
function changeHeat(v){const t=Math.min(1,Math.abs(v)/10),from=[245,243,236],to=v<0?[65,112,165]:[181,106,49];return`rgb(${from.map((value,i)=>Math.round(value+(to[i]-value)*t)).join(',')})`;}
const memberships={
oecd:new Set('AUS AUT BEL CAN CHL COL CRI CZE DNK EST FIN FRA DEU GRC HUN ISL IRL ISR ITA JPN KOR LVA LTU LUX MEX NLD NZL NOR POL PRT SVK SVN ESP SWE CHE TUR GBR USA'.split(' ')),
eu:new Set('AUT BEL BGR HRV CYP CZE DNK EST FIN FRA DEU GRC HUN IRL ITA LVA LTU LUX MLT NLD POL PRT ROU SVK SVN ESP SWE'.split(' ')),
g20:new Set('ARG AUS BRA CAN CHN FRA DEU IND IDN ITA JPN KOR MEX RUS SAU ZAF TUR GBR USA'.split(' '))};
const groups={continent:{label:'Continent',cats:continents,colors:color},oecd:{label:'OECD',cats:['OECD members','Non-members'],colors:{'OECD members':'#1f6666','Non-members':'#c0863a'}},g20:{label:'G20',cats:['G20 members','Other countries'],colors:{'G20 members':'#1f6666','Other countries':'#c0863a'}},eu:{label:'EU',cats:['EU members','Other countries'],colors:{'EU members':'#2f5fa8','Other countries':'#c0863a'}},income:{label:'Income quartile',cats:['Top 25%','Upper-middle','Lower-middle','Bottom 25%'],colors:{'Top 25%':'#173f4f','Upper-middle':'#2f7f86','Lower-middle':'#7fb3a6','Bottom 25%':'#c0863a'}}};
const orderedIncome=[...DATA.countries].sort((a,b)=>a.gdp-b.gdp||a.code.localeCompare(b.code));
const quartiles=new Map(orderedIncome.map((c,i)=>[c.code,['Bottom 25%','Lower-middle','Upper-middle','Top 25%'][Math.min(3,Math.floor(4*i/orderedIncome.length))]]));
function category(c){if(groupBy==='continent')return c.continent;if(groupBy==='income')return quartiles.get(c.code);return memberships[groupBy].has(c.code)?groups[groupBy].cats[0]:groups[groupBy].cats[1];}
function colorOf(c){return groups[groupBy].colors[category(c)];}
function change(c){const h=c.history;return h.length?{from:h[0][0],to:h.at(-1)[0],d:h.at(-1)[1]-h[0][1]}:{from:2000,to:2024,d:0};}
function signed(n,digits=1){return(n>=0?'+':'−')+Math.abs(n).toFixed(digits);}
function sortedRows(){const sorters={change:(a,b)=>change(b).d-change(a).d,level:(a,b)=>b.spending-a.spending,income:(a,b)=>b.gdp-a.gdp,name:(a,b)=>a.name.localeCompare(b.name)};return [...visible].sort((a,b)=>sorters[sortBy](a,b)||a.name.localeCompare(b.name));}
function renderLegend(){
  $('legend').replaceChildren();
  for(const name of groups[groupBy].cats){const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(enabled.has(name)));const sw=document.createElement('span');sw.className='swatch';sw.style.setProperty('--series',groups[groupBy].colors[name]);sw.setAttribute('aria-hidden','true');b.appendChild(sw);b.appendChild(document.createTextNode(name));const count=document.createElement('span');count.textContent=DATA.countries.filter(c=>category(c)===name).length;b.appendChild(count);b.addEventListener('click',()=>{enabled.has(name)?enabled.delete(name):enabled.add(name);b.setAttribute('aria-pressed',String(enabled.has(name)));update(false);});$('legend').appendChild(b);}
  const b=document.createElement('button');b.type='button';b.className='reset';b.textContent='Show all';b.onclick=()=>{enabled=new Set(groups[groupBy].cats);update();};$('legend').appendChild(b);
}
for(const [key,g]of Object.entries(groups)){const b=document.createElement('button');b.type='button';b.textContent=g.label;b.dataset.group=key;b.setAttribute('aria-pressed',String(key===groupBy));b.onclick=()=>{groupBy=key;enabled=new Set(g.cats);$('groups').querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.group===key)));update();};$('groups').appendChild(b);}
for(const [key,label]of [['change','Change'],['level','2024 share'],['income','Income'],['name','A–Z']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.sort=key;b.setAttribute('aria-pressed',String(key===sortBy));b.onclick=()=>{sortBy=key;$('sorts').querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.sort===key)));renderTrends();};$('sorts').appendChild(b);}
for(const c of DATA.countries){$('country-list').appendChild(new Option(c.name,c.name));$('country-select').add(new Option(c.name,c.code));}
$('country-select').addEventListener('change',e=>{const c=DATA.countries.find(c=>c.code===e.target.value);enabled.add(category(c));selected=c.code;$('search').value=c.name;update();});
$('search').addEventListener('input',e=>{const c=DATA.countries.find(c=>c.name.toLowerCase()===e.target.value.trim().toLowerCase());if(c){enabled.add(category(c));selected=c.code;update();}});
function selectCountry(code){selected=code;$('search').value='';drawScatter();updateDetail();document.querySelectorAll('.facet,.heat-row').forEach(n=>{const is=n.dataset.code===code;n.classList.toggle('selected',is);if(n.classList.contains('heat-row'))n.setAttribute('aria-pressed',String(is));});}
function updateDetail(){
const c=DATA.countries.find(c=>c.code===selected);if(!c)return;
$('selected-name').textContent=c.name;$('country-select').value=c.code;
const tags=Object.entries(memberships).filter(([,set])=>set.has(c.code)).map(([k])=>k.toUpperCase());
$('country-tags').replaceChildren();const sw=document.createElement('span');sw.className='swatch';sw.style.setProperty('--series',colorOf(c));sw.style.marginRight='7px';$('country-tags').appendChild(sw);$('country-tags').appendChild(document.createTextNode([c.continent,...tags].join(' · ')));
const f=fit(visible),inside=visible.some(v=>v.code===c.code),res=f&&inside?c.spending-f.a-f.b*Math.log(c.gdp):null,ch=change(c);
$('selected-detail').replaceChildren();for(const [label,value]of [['Spending, % of GDP',c.spending.toFixed(1)+'%'],['GDP per person','$'+Math.round(c.gdp).toLocaleString('en-US')],['Versus fit line',res===null?'n/a':signed(res)+' pp'],['Change since '+ch.from,signed(ch.d)+' pp']]){const div=document.createElement('div'),l=document.createElement('span'),v=document.createElement('strong');l.textContent=label;v.textContent=value;div.append(l,v);$('selected-detail').appendChild(div);}
$('exact-values').textContent=`Exact 2024 values: ${format(c.spending)}% of GDP · ${format(c.gdp)} international dollars per person.`;
$('country-note').textContent=`2024 · PPP, constant 2021 international dollars. Spending includes transfers and interest where represented by the source. ${inside?'':'Outside the active filters; shown for reference. '}${c.annotation?'Source note: '+c.annotation:''}`;
$('mobile-summary').replaceChildren();const n=document.createElement('strong');n.textContent=c.name;const v=document.createElement('span');v.textContent=`${c.spending.toFixed(1)}% of GDP · $${Math.round(c.gdp).toLocaleString('en-US')} / person · ${signed(ch.d)} pp since ${ch.from}`;$('mobile-summary').append(n,v);drawDetail(c);
}
function drawDetail(c){const svg=$('detail-trend'),W=svg.parentElement.clientWidth,H=164,m={l:27,r:50,t:13,b:28},pw=W-m.l-m.r,ph=H-m.t-m.b,x=yr=>m.l+(yr-2000)/24*pw,y=v=>m.t+(yDomain[1]-v)/(yDomain[1]-yDomain[0])*ph;svg.replaceChildren();svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('aria-label',`${c.name} spending share, 2000–2024. Shared ${yDomain.join('–')} percent scale. 2024: ${format(c.spending)} percent.`);
for(const value of [0,50,100]){el('line',{x1:m.l,x2:W-m.r,y1:y(value),y2:y(value),class:'grid'},svg);txt(svg,m.l-5,y(value)+3,value,{'text-anchor':'end','font-size':10});}el('line',{x1:x(2020),x2:x(2020),y1:m.t,y2:m.t+ph,stroke:'var(--muted)','stroke-dasharray':'2 3','stroke-width':.8},svg);txt(svg,m.l,H-7,'2000');txt(svg,x(2024),H-7,'2024',{'text-anchor':'end'});let d='',last=null;for(const [yr,v]of c.history){d+=(last===yr-1?'L':'M')+x(yr)+','+y(v);last=yr;}el('path',{d,stroke:colorOf(c),fill:'none','stroke-width':2,'stroke-linejoin':'round','stroke-linecap':'round'},svg);for(const [yr,v]of c.history)el('circle',{cx:x(yr),cy:y(v),r:1.5,fill:colorOf(c),opacity:.4},svg);el('circle',{cx:x(2024),cy:y(c.spending),r:3.5,fill:colorOf(c)},svg);txt(svg,x(2024)+6,y(c.spending)+4,c.spending.toFixed(1)+'%',{class:'end-label'});
const guide=el('line',{x1:0,x2:0,y1:m.t,y2:m.t+ph,stroke:'var(--ink)',visibility:'hidden','stroke-width':.8},svg),hit=el('rect',{x:m.l,y:m.t,width:pw,height:ph,fill:'transparent'},svg);
function inspect(e){const b=svg.getBoundingClientRect(),yr=Math.max(2000,Math.min(2024,Math.round(2000+((e.clientX-b.left)*W/b.width-m.l)/pw*24))),ob=c.history.find(h=>h[0]===yr);if(!ob)return;guide.setAttribute('x1',x(yr));guide.setAttribute('x2',x(yr));guide.setAttribute('visibility','visible');$('mini-value').textContent=yr+': '+ob[1].toFixed(1)+'%';tooltip(`<strong>${c.name} · ${yr}</strong><div>Government expenditure: ${format(ob[1])}% of GDP</div>`,e);}
hit.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')inspect(e);});hit.addEventListener('click',e=>{pinned=true;inspect(e);});hit.addEventListener('pointerleave',()=>{guide.setAttribute('visibility','hidden');$('mini-value').textContent='';hideTip();});
}
function heat(v){const t=Math.max(0,Math.min(1,(v-10)/50));return`oklch(${(.96-t*.66).toFixed(3)} ${(.02+Math.sin(t*Math.PI)*.08).toFixed(3)} ${(195+t*30).toFixed(0)})`;}
function renderHeatmap(){const container=$('heatmap');container.replaceChildren();if(trendView!=='heatmap')return;const rows=sortedRows(),cols=container.clientWidth>=820?2:1;container.classList.toggle('two-columns',cols===2);const per=Math.ceil(rows.length/cols);
for(let col=0;col<cols;col++){const column=document.createElement('div');column.className='heat-column';const head=document.createElement('div');head.className='heat-head';head.innerHTML='<span></span><span class="year-axis"><span style="left:0">2000</span><span style="left:42%;transform:translateX(-50%)">2010</span><span style="left:82%;transform:translateX(-50%)">2020</span><span style="right:0;top:11px">2024</span></span><span>Δ pp</span>';column.appendChild(head);
for(const c of rows.slice(col*per,(col+1)*per)){const row=document.createElement('button');row.type='button';row.className='heat-row'+(c.code===selected?' selected':'');row.dataset.code=c.code;row.setAttribute('aria-pressed',String(c.code===selected));row.setAttribute('aria-label',`${c.name}, 2024 spending ${format(c.spending)} percent of GDP; change ${signed(change(c).d)} percentage points since ${change(c).from}. Select to inspect.`);const name=document.createElement('span');name.className='heat-name';const sw=document.createElement('span');sw.className='swatch';sw.style.setProperty('--series',colorOf(c));sw.setAttribute('aria-hidden','true');const n=document.createElement('span');n.className='country-name';n.textContent=c.name;name.append(sw,n);row.appendChild(name);
const cells=document.createElement('span');cells.className='heat-cells';cells.setAttribute('aria-hidden','true');const obs=historyLookup.get(c.code);for(let i=0;i<25;i++){const cell=document.createElement('span');cell.className='heat-cell';cell.dataset.year=2000+i;const value=heatMeasure==='change'?annualChange(c,2000+i):obs.get(2000+i);if(value!==undefined){cell.style.background=heatMeasure==='change'?changeHeat(value):heat(value);cell.dataset.value=value;}else{cell.dataset.missing='true';cell.style.background='repeating-linear-gradient(45deg,transparent 0 2px,#d9ddd8 2px 3px)';}cells.appendChild(cell);}row.appendChild(cells);const delta=document.createElement('span');delta.className='heat-delta';delta.textContent=signed(change(c).d);delta.title='Total change, 2000–2024 (percentage points)';row.appendChild(delta);
function show(e){const bounds=cells.getBoundingClientRect();if(e.clientX<bounds.left||e.clientX>bounds.right)return;const year=2000+Math.min(24,Math.max(0,Math.floor((e.clientX-bounds.left)/bounds.width*25))),v=obs.get(year),diff=annualChange(c,year);tooltip(`<strong>${c.name} · ${year}</strong><div>Government expenditure: ${v===undefined?'no data':format(v)+'% of GDP'}</div><div>Annual change: ${diff===undefined?'not available (no consecutive prior-year observation)':signed(diff,6).replace(/\.?0+$/,'')+' pp vs '+(year-1)}</div><div class="tip-note">${c.continent} · Total change since ${change(c).from}: ${signed(change(c).d)} pp</div>`,e);}
row.addEventListener('pointermove',e=>{if(e.pointerType!=='touch'&&!pinned)show(e);});row.addEventListener('pointerleave',hideTip);row.addEventListener('click',e=>{selectCountry(c.code);pinned=true;show(e);});column.appendChild(row);}container.appendChild(column);}}
function renderTrends(){pinned=false;hideTip();$('heatmap').hidden=trendView!=='heatmap';$('facets').hidden=trendView!=='facets';$('heat-key').hidden=trendView!=='heatmap';$('heat-measures').hidden=trendView!=='heatmap';$('heat-description').hidden=trendView!=='heatmap';$('trend-description').hidden=trendView!=='facets';renderHeatmap();renderFacets();$('facet-count').textContent=`${visible.length} of ${DATA.countries.length} countries · ${groups[groupBy].label.toLowerCase()} grouping`;$('empty').hidden=visible.length>0;}
for(const button of $('view-controls').querySelectorAll('button'))button.onclick=()=>{trendView=button.dataset.view;$('view-controls').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderTrends();};
function update(redrawLegend=true){pinned=false;hideTip();visible=DATA.countries.filter(c=>enabled.has(category(c)));if(redrawLegend)renderLegend();$('filter-status').textContent=`${visible.length} of ${DATA.countries.length} countries included in the fit and trend view${groupBy==='income'?' · Quartiles of this sample, not World Bank income classes':''}. Grey dots are excluded context.`;drawScatter();updateDetail();renderTrends();$('data-table').replaceChildren();for(const c of visible){const tr=document.createElement('tr');for(const value of [c.name,c.continent,format(c.gdp),format(c.spending)]){const td=document.createElement('td');td.textContent=value;tr.appendChild(td);}$('data-table').appendChild(tr);}}
const fullFit=fit(DATA.countries);$('hero-slope').textContent=signed(fullFit.b*Math.log(2));$('hero-r2').textContent=fullFit.r2.toFixed(2);$('hero-count').textContent=DATA.countries.length;
const membershipNote=document.createElement('p');membershipNote.innerHTML='Groupings use membership checked October 26, 2026: <a href="https://www.oecd.org/en/about/members-partners.html">OECD</a> (38 members), <a href="https://european-union.europa.eu/principles-countries-history/eu-countries_en">EU</a> (27) and <a href="https://www.g20.org.za/about-g20/g20-members/">G20</a> (19 member countries; EU and African Union blocs excluded). Lithuania and Malta lack matched data. Income quartiles rank this 149-country sample by 2024 PPP GDP per person, split into four groups of approximately equal size; these are not World Bank income classes. Group filters refit the line and recolor included countries. Grey context dots are excluded from the fit and trend view. The full-sample headline statistics remain fixed.';$('match-method').parentElement.appendChild(membershipNote);
const heatScale=document.createElement('span');heatScale.id='heat-scale';while($('heat-key').firstChild)heatScale.appendChild($('heat-key').firstChild);$('heat-key').appendChild(heatScale);
const measureControls=document.createElement('div');measureControls.id='heat-measures';measureControls.className='segmented';measureControls.setAttribute('role','group');measureControls.setAttribute('aria-label','Heatmap measure');$('view-controls').after(measureControls);
for(const [value,label]of [['level','Spending level'],['change','Annual change']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.measure=value;b.setAttribute('aria-pressed',String(value===heatMeasure));b.setAttribute('aria-controls','heatmap');b.onclick=()=>{heatMeasure=value;measureControls.querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));updateHeatScale();renderTrends();};measureControls.appendChild(b);}
const measureStatus=document.createElement('span');measureStatus.className='sr-only';measureStatus.setAttribute('role','status');measureControls.after(measureStatus);
function updateHeatScale(){heatScale.innerHTML=heatMeasure==='change'?'<span>≤−10 pp</span><span class="change-gradient" aria-label="Blue: decrease; neutral: zero; orange: increase"></span><span>≥+10 pp</span><span class="missing-key"></span><span>No change data</span>':'<span>≤10%</span><span class="gradient"></span><span>60%+</span><span class="missing-key"></span><span>No data</span>';$('heat-description').textContent=heatMeasure==='change'?'Each cell shows the change from the preceding year, in percentage points of GDP. Blue indicates a decrease; orange an increase; the neutral midpoint is zero. Colors saturate at ±10 pp; tooltips retain exact values. 2000 is unavailable because the displayed series starts that year; missing consecutive years are not bridged. The right column remains total change from 2000 to 2024.':'Each row is a country; each cell is one year’s government expenditure as a share of GDP. Darker is higher. The right column is the total change from 2000 to 2024. Select a row to inspect it.';measureStatus.textContent=heatMeasure==='change'?'Annual change in percentage points. Color scale centered at zero.':'Spending level as a percentage of GDP.';}
const highlight2020=document.createElement('button');highlight2020.type='button';highlight2020.id='highlight-2020';highlight2020.textContent='Highlight 2020';highlight2020.setAttribute('aria-pressed','false');highlight2020.setAttribute('aria-controls','heatmap');highlight2020.title='Emphasize the COVID-year column across all country rows';$('heat-key').appendChild(highlight2020);
const highlightStatus=document.createElement('span');highlightStatus.className='sr-only';highlightStatus.setAttribute('role','status');$('heat-key').appendChild(highlightStatus);
highlight2020.addEventListener('click',()=>{const on=highlight2020.getAttribute('aria-pressed')!=='true';highlight2020.setAttribute('aria-pressed',String(on));$('heatmap').classList.toggle('highlight-2020',on);highlightStatus.textContent=on?'2020 highlighted across all country rows. Other years are muted.':'All years shown at normal emphasis.';});
update();let lastWidth=0;const ro=new ResizeObserver(()=>{document.documentElement.style.setProperty('--filter-height',$('filter-bar').offsetHeight+'px');const w=$('scatter').parentElement.clientWidth;if(w!==lastWidth){lastWidth=w;pinned=false;hideTip();drawScatter();drawFacets();renderHeatmap();updateDetail();}});ro.observe($('project'));ro.observe($('filter-bar'));
